/**
 * A closing call to action: a heading, one sentence and one or two links. Axes: layout (card, band, split
 * picture, row: heading beside the button in a card), tone, actions (one, two, form: an email field), proof
 * (none, quote), density.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Card } from "../primitives/card/card";
import { CardContent } from "../primitives/card/card-content";
import { Container } from "../primitives/container/container";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { CtaActions } from "../components/cta-actions";
import { CtaBanner } from "../blocks/cta-banner";
import { MediaFrame } from "../components/media-frame";
import { QuoteProof } from "../components/quote-proof";
import { SectionFrame } from "../components/section-frame";
import { tpl } from "../utils";
import type { CtaQuote } from "./cta-band.types";
import type { ActionSet } from "../components/cta-actions.types";

export type CtaBandProps = {
  id: string;
  title: string;
  text: string;
  actions: ActionSet;
  quote?: CtaQuote;
  layout?: "card" | "band" | "split" | "row" | "banner";
  tone?: "default" | "muted";
  proof?: "none" | "quote";
  density?: "roomy" | "default" | "compact";
  landmarkLabel?: string;
};

export function CtaBand({
  id,
  title,
  text,
  actions,
  quote,
  layout = "card",
  tone = "muted",
  proof = "none",
  density = "default",
  landmarkLabel,
}: CtaBandProps) {
  const center = ((layout as string) === "band") || ((layout as string) === "banner");
  return (
    <>
      {((layout as string) === "banner") ? (
        <CtaBanner
          id={id}
          title={title}
          text={text}
          cta={actions.cta}
          href={actions.href}
          tone={tone}
          landmarkLabel={landmarkLabel}
        />
      ) : ((layout as string) === "row") ? (
        <Block
          tag="section"
          className="py-8"
          aria-labelledby={(landmarkLabel ? undefined : tpl("{0}-title", id))}
          data-testid="section"
          data-tone={tone}
          data-density={density}
          aria-label={landmarkLabel}
        >
          <Container className="mx-auto w-full max-w-6xl px-4" data-slot="container">
            <Card variant="muted">
              <CardContent className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <Stack gap="2" className="min-w-0">
                  <Title as={2} size="2xl" weight="bold" id={tpl("{0}-title", id)}>
                    {title}
                  </Title>
                  <Text size="base" className="text-muted-foreground">
                    {text}
                  </Text>
                </Stack>
                {((proof as string) === "quote") ? (
                  <QuoteProof quote={quote?.text} quoteBy={quote?.by} center={center} />
                ) : null}
                <CtaActions id={id} actions={actions} center={center} />
              </CardContent>
            </Card>
          </Container>
        </Block>
      ) : (
        <SectionFrame
          id={id}
          title={title}
          lead={text}
          layout={(((layout as string) === "split") ? "split" : "stack")}
          align={(center ? "center" : "start")}
          boxed={((layout as string) === "card")}
          media={{ show: ((layout as string) === "split") }}
          tone={tone}
          density={density}
          landmarkLabel={landmarkLabel}
          aside={(
            <MediaFrame alt={title} ratio="4/3" />
          )}
        >
          {((proof as string) === "quote") ? (
            <QuoteProof quote={quote?.text} quoteBy={quote?.by} center={center} />
          ) : null}
          <CtaActions id={id} actions={actions} center={center} />
        </SectionFrame>
      )}
    </>
  );
}

